import React, {useState} from 'react';
import './App.css';
// eslint-disable-next-line
import {BrowserRouter as Router, Routes, Route} from 'react-router-dom';
import Navbar from './components/Navbar';



function App(){

  return(
    <>
    <router>
     <Navbar />
      <routes>
        <route path="/" element={<h3 className="home">Home</h3>}></route>
      </routes>
    </router>
    <h1 className="logo">Amba Traders</h1>
    </>

  );
}



export default App;
